arguments.content:
/* ShiftWise - Restaurant Team Management SaaS */
/* Color Palette: Deep Navy #1a1f36, Vibrant Orange #ff6b35, White #ffffff, Light Gray #f5f7fa */

:root {
  --primary: #1a1f36;
  --accent: #ff6b35;
  --accent-hover: #e55a2b;
  --white: #ffffff;
  --gray-50: #f5f7fa;
  --gray-100: #e8ecf1;
  --gray-200: #d1d9e6;
  --gray-300: #b0bcc9;
  --gray-400: #8a9ab0;
  --gray-500: #5c6b7f;
  --gray-600: #3d4a5c;
  --text-primary: #1a1f36;
  --text-secondary: #5c6b7f;
  --text-light: #8a9ab0;
  --border: #e8ecf1;
  --shadow-sm: 0 1px 3px rgba(26,31,54,0.08);
  --shadow-md: 0 4px 12px rgba(26,31,54,0.1);
  --shadow-lg: 0 8px 30px rgba(26,31,54,0.12);
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --transition: 0.25s ease;
}

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  font-size: 16px;
  line-height: 1.6;
  color: var(--text-primary);
  background: var(--white);
  -webkit-font-smoothing: antialiased;
}

h1, h2, h3, h4, h5, h6 {
  font-family: 'DM Sans', -apple-system, BlinkMacSystemFont, sans-serif;
  font-weight: 700;
  line-height: 1.2;
  color: var(--primary);
}

h1 { font-size: clamp(2rem, 5vw, 3.5rem); }
h2 { font-size: clamp(1.75rem, 4vw, 2.5rem); }
h3 { font-size: clamp(1.25rem, 2.5vw, 1.5rem); }
h4 { font-size: 1.125rem; }

p {
  color: var(--text-secondary);
}

a {
  color: var(--accent);
  text-decoration: none;
  transition: var(--transition);
}

a:hover {
  color: var(--accent-hover);
}

img {
  max-width: 100%;
  height: auto;
}

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 14px 28px;
  font-family: 'DM Sans', sans-serif;
  font-size: 1rem;
  font-weight: 600;
  border-radius: var(--radius-md);
  border: none;
  cursor: pointer;
  transition: var(--transition);
  text-decoration: none;
}

.btn-primary {
  background: var(--accent);
  color: var(--white);
}

.btn-primary:hover {
  background: var(--accent-hover);
  color: var(--white);
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.btn-secondary {
  background: var(--white);
  color: var(--primary);
  border: 2px solid var(--border);
}

.btn-secondary:hover {
  border-color: var(--primary);
  color: var(--primary);
}

.btn-large {
  padding: 18px 36px;
  font-size: 1.125rem;
}

.btn-sm {
  padding: 10px 20px;
  font-size: 0.875rem;
}

/* Header */
.header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: rgba(255,255,255,0.95);
  backdrop-filter: blur(10px);
  border-bottom: 1px solid var(--border);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
}

.logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-family: 'DM Sans', sans-serif;
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--primary);
}

.logo svg {
  width: 36px;
  height: 36px;
}

.nav {
  display: flex;
  align-items: center;
  gap: 32px;
}

.nav-links {
  display: flex;
  gap: 32px;
  list-style: none;
}

.nav-links a {
  color: var(--text-secondary);
  font-weight: 500;
  transition: var(--transition);
}

.nav-links a:hover,
.nav-links a.active {
  color: var(--primary);
}

.nav-cta {
  display: flex;
  gap: 12px;
}

/* Mobile Menu */
.hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: 8px;
  background: none;
  border: none;
  cursor: pointer;
}

.hamburger span {
  width: 24px;
  height: 2px;
  background: var(--primary);
  border-radius: 2px;
  transition: var(--transition);
}

.mobile-nav {
  display: none;
  position: fixed;
  top: 72px;
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--white);
  padding: 24px;
  z-index: 999;
}

.mobile-nav.active {
  display: block;
}

.mobile-nav-links {
  display: flex;
  flex-direction: column;
  gap: 16px;
  list-style: none;
  margin-bottom: 24px;
}

.mobile-nav-links a {
  display: block;
  padding: 12px 0;
  font-size: 1.125rem;
  font-weight: 500;
  color: var(--text-primary);
  border-bottom: 1px solid var(--border);
}

.mobile-nav-cta {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

/* Hero */
.hero {
  padding: 160px 0 80px;
  background: linear-gradient(180deg, var(--gray-50) 0%, var(--white) 100%);
}

.hero-content {
  max-width: 720px;
}

.hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 8px 16px;
  background: rgba(255,107,53,0.1);
  color: var(--accent);
  font-size: 0.875rem;
  font-weight: 600;
  border-radius: 50px;
  margin-bottom: 24px;
}

.hero h1 {
  margin-bottom: 24px;
}

.hero-subtitle {
  font-size: 1.25rem;
  color: var(--text-secondary);
  margin-bottom: 32px;
  max-width: 560px;
}

.hero-cta {
  display: flex;
  gap: 16px;
  flex-wrap: wrap;
}

/* Section Styling */
.section {
  padding: 80px 0;
}

.section-gray {
  background: var(--gray-50);
}

.section-header {
  text-align: center;
  max-width: 640px;
  margin: 0 auto 56px;
}

.section-header p {
  margin-top: 16px;
  font-size: 1.125rem;
}

.section-label {
  display: inline-block;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--accent);
  text-transform: uppercase;
  letter-spacing: 1px;
  margin-bottom: 12px;
}

/* Features Grid */
.features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 32px;
}

.feature-card {
  padding: 32px;
  background: var(--white);
  border-radius: var(--radius-lg);
  border: 1px solid var(--border);
  transition: var(--transition);
}

.feature-card:hover {
  border-color: var(--accent);
  box-shadow: var(--shadow-md);
  transform: translateY(-4px);
}

.feature-icon {
  width: 56px;
  height: 56px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(255,107,53,0.1);
  border-radius: var(--radius-md);
  margin-bottom: 20px;
}

.feature-icon svg {
  width: 28px;
  height: 28px;
  color: var(--accent);
}

.feature-card h3 {
  margin-bottom: 12px;
}

.feature-card p {
  font-size: 0.9375rem;
}

/* How It Works */
.steps {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: 40px;
}

.step {
  text-align: center;
  position: relative;
}

.step-number {
  width: 48px;
  height: 48px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--accent);
  color: var(--white);
  font-family: 'DM Sans', sans-serif;
  font-size: 1.25rem;
  font-weight: 700;
  border-radius: 50%;
  margin: 0 auto 20px;
}

.step h3 {
  margin-bottom: 12px;
}

.step p {
  font-size: 0.9375rem;
}

/* Testimonials */
.testimonial-carousel {
  position: relative;
  max-width: 800px;
  margin: 0 auto;
  overflow: hidden;
}

.testimonial-track {
  display: flex;
  transition: transform 0.5s ease;
}

.testimonial-card {
  flex: 0 0 100%;
  padding: 48px;
  background: var(--white);
  border-radius: var(--radius-lg);
  text-align: center;
  box-shadow: var(--shadow-md);
}

.testimonial-quote {
  font-size: 1.25rem;
  font-style: italic;
  color: var(--text-primary);
  margin-bottom: 24px;
  line-height: 1.7;
}

.testimonial-author {
  font-weight: 600;
  color: var(--primary);
}

.testimonial-role {
  color: var(--text-light);
  font-size: 0.875rem;
}

.testimonial-nav {
  display: flex;
  justify-content: center;
  gap: 16px;
  margin-top: 32px;
}

.testimonial-nav button {
  width: 48px;
  height: 48px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--white);
  border: 1px solid var(--border);
  border-radius: 50%;
  cursor: pointer;
  transition: var(--transition);
}

.testimonial-nav button:hover {
  background: var(--accent);
  border-color: var(--accent);
  color: var(--white);
}

.testimonial-nav button svg {
  width: 20px;
  height: 20px;
}

.testimonial-dots {
  display: flex;
  justify-content: center;
  gap: 8px;
  margin-top: 24px;
}

.testimonial-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--gray-200);
  border: none;
  cursor: pointer;
  transition: var(--transition);
}

.testimonial-dot.active {
  background: var(--accent);
  width: 28px;
  border-radius: 5px;
}

/* Stats */
.stats-banner {
  background: var(--primary);
  padding: 64px 0;
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 48px;
  text-align: center;
}

.stat-item {
  color: var(--white);
}

.stat-number {
  font-family: 'DM Sans', sans-serif;
  font-size: clamp(2rem, 5vw, 3rem);
  font-weight: 700;
  color: var(--accent);
  margin-bottom: 8px;
}

.stat-label {
  font-size: 1rem;
  opacity: 0.8;
}

/* Pricing */
.pricing-toggle {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  margin-bottom: 48px;
}

.toggle-label {
  font-weight: 500;
  color: var(--text-secondary);
}

.toggle-label.active {
  color: var(--primary);
}

.toggle-switch {
  width: 56px;
  height: 30px;
  background: var(--gray-200);
  border-radius: 15px;
  position: relative;
  cursor: pointer;
  transition: var(--transition);
}

.toggle-switch.active {
  background: var(--accent);
}

.toggle-switch::after {
  content: '';
  position: absolute;
  width: 24px;
  height: 24px;
  background: var(--white);
  border-radius: 50%;
  top: 3px;
  left: 3px;
  transition: var(--transition);
  box-shadow: var(--shadow-sm);
}

.toggle-switch.active::after {
  left: 29px;
}

.save-badge {
  padding: 4px 12px;
  background: rgba(255,107,53,0.1);
  color: var(--accent);
  font-size: 0.75rem;
  font-weight: 600;
  border-radius: 50px;
}

.pricing-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 32px;
  max-width: 1000px;
  margin: 0 auto;
}

.pricing-card {
  padding: 40px;
  background: var(--white);
  border-radius: var(--radius-lg);
  border: 2px solid var(--border);
  text-align: center;
  transition: var(--transition);
}

.pricing-card.featured {
  border-color: var(--accent);
  transform: scale(1.02);
  box-shadow: var(--shadow-lg);
}

.pricing-card:hover {
  transform: translateY(-4px);
}

.pricing-card.featured:hover {
  transform: scale(1.02) translateY(-4px);
}

.pricing-label {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--accent);
  text-transform: uppercase;
  letter-spacing: 1px;
  margin-bottom: 8px;
}

.pricing-name {
  font-size: 1.5rem;
  margin-bottom: 16px;
}

.pricing-price {
  margin-bottom: 24px;
}

.pricing-amount {
  font-family: 'DM Sans', sans-serif;
  font-size: 3rem;
  font-weight: 700;
  color: var(--primary);
}

.pricing-period {
  color: var(--text-light);
}

.pricing-features {
  list-style: none;
  margin-bottom: 32px;
  text-align: left;
}

.pricing-features li {
  padding: 12px 0;
  border-bottom: 1px solid var(--border);
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: 0.9375rem;
}

.pricing-features li:last-child {
  border-bottom: none;
}

.pricing-features .check {
  width: 20px;
  height: 20px;
  color: var(--accent);
  flex-shrink: 0;
}

.pricing-features .no {
  width: 20px;
  height: 20px;
  color: var(--gray-300);
  flex-shrink: 0;
}

/* FAQ */
.faq-list {
  max-width: 800px;
  margin: 0 auto;
}

.faq-item {
  border-bottom: 1px solid var(--border);
}

.faq-question {
  width: 100%;
  padding: 24px 0;
  background: none;
  border: none;
  text-align: left;
  font-size: 1.125rem;
  font-weight: 600;
  color: var(--primary);
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
}

.faq-question svg {
  width: 24px;
  height: 24px;
  color: var(--text-light);
  transition: var(--transition);
  flex-shrink: 0;
}

.faq-item.active .faq-question svg {
  transform: rotate(180deg);
  color: var(--accent);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease;
}

.faq-item.active .faq-answer {
  max-height: 200px;
}

.faq-answer p {
  padding-bottom: 24px;
}

/* CTA Section */
.cta-section {
  background: var(--primary);
  padding: 80px 0;
  text-align: center;
}

.cta-section h2 {
  color: var(--white);
  margin-bottom: 16px;
}

.cta-section p {
  color: rgba(255,255,255,0.8);
  font-size: 1.125rem;
  margin-bottom: 32px;
}

.cta-section .btn-primary {
  background: var(--accent);
}

/* Team Grid */
.team-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: 32px;
}

.team-card {
  text-align: center;
  padding: 32px;
  background: var(--white);
  border-radius: var(--radius-lg);
  border: 1px solid var(--border);
}

.team-avatar {
  width: 80px;
  height: 80px;
  background: var(--gray-100);
  border-radius: 50%;
  margin: 0 auto 16px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--accent);
}

.team-name {
  font-size: 1.125rem;
  margin-bottom: 4px;
}

.team-role {
  color: var(--text-light);
  font-size: 0.875rem;
}

/* Contact Form */
.contact-form {
  max-width: 600px;
  margin: 0 auto;
  padding: 48px;
  background: var(--white);
  border-radius: var(--radius-lg);
  border: 1px solid var(--border);
  box-shadow: var(--shadow-md);
}

.form-group {
  margin-bottom: 24px;
}

.form-group label {
  display: block;
  font-weight: 500;
  margin-bottom: 8px;
  color: var(--primary);
}

.form-group input,
.form-group select,
.form-group textarea {
  width: 100%;
  padding: 14px 16px;
  font-size: 1rem;
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  background: var(--white);
  transition: var(--transition);
  font-family: inherit;
}

.form-group input:focus,
.form-group select:focus,
.form-group textarea:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(255,107,53,0.1);
}

.form-group textarea {
  min-height: 120px;
  resize: vertical;
}

.form-group.error input,
.form-group.error select,
.form-group.error textarea {
  border-color: #e53e3e;
}

.form-error {
  color: #e53e3e;
  font-size: 0.875rem;
  margin-top: 6px;
  display: none;
}

.form-group.error .form-error {
  display: block;
}

.form-success {
  display: none;
  padding: 24px;
  background: rgba(72, 187, 120, 0.1);
  border: 1px solid #48bb78;
  border-radius: var(--radius-md);
  text-align: center;
  color: #2f855a;
  margin-bottom: 24px;
}

.form-success.show {
  display: block;
}

/* Office Locations */
.office-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: 32px;
  margin-top: 48px;
}

.office-card {
  padding: 32px;
  background: var(--gray-50);
  border-radius: var(--radius-md);
  text-align: center;
}

.office-card h4 {
  margin-bottom: 8px;
}

.office-card p {
  font-size: 0.9375rem;
}

/* Footer */
.footer {
  background: var(--primary);
  color: var(--white);
  padding: 64px 0 32px;
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr repeat(3, 1fr);
  gap: 48px;
  margin-bottom: 48px;
}

.footer-brand p {
  color: rgba(255,255,255,0.7);
  margin-top: 16px;
  max-width: 280px;
}

.footer-column h5 {
  color: var(--white);
  font-size: 0.875rem;
  text-transform: uppercase;
  letter-spacing: 1px;
  margin-bottom: 20px;
}

.footer-links {
  list-style: none;
}

.footer-links li {
  margin-bottom: 12px;
}

.footer-links a {
  color: rgba(255,255,255,0.7);
  font-size: 0.9375rem;
  transition: var(--transition);
}

.footer-links a:hover {
  color: var(--white);
}

.footer-bottom {
  padding-top: 32px;
  border-top: 1px solid rgba(255,255,255,0.1);
  text-align: center;
  color: rgba(255,255,255,0.5);
  font-size: 0.875rem;
}

/* Page Header */
.page-header {
  padding: 140px 0 60px;
  background: var(--gray-50);
  text-align: center;
}

.page-header h1 {
  margin-bottom: 16px;
}

.page-header p {
  font-size: 1.25rem;
  max-width: 600px;
  margin: 0 auto;
}

/* Feature Detail Sections */
.feature-detail {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}

.feature-detail.reverse {
  direction: rtl;
}

.feature-detail.reverse > * {
  direction: ltr;
}

.feature-detail-content h3 {
  margin-bottom: 16px;
}

.feature-detail-content p {
  margin-bottom: 24px;
}

.feature-detail-visual {
  background: var(--gray-50);
  border-radius: var(--radius-lg);
  height: 320px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-light);
}

/* Integration Grid */
.integration-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 24px;
}

.integration-category {
  padding: 24px;
  background: var(--white);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
}

.integration-category h4 {
  margin-bottom: 16px;
  color: var(--accent);
}

.integration-category ul {
  list-style: none;
}

.integration-category li {
  padding: 8px 0;
  color: var(--text-secondary);
  font-size: 0.9375rem;
  border-bottom: 1px solid var(--border);
}

.integration-category li:last-child {
  border-bottom: none;
}

/* Mission Section */
.mission-content {
  max-width: 800px;
  margin: 0 auto;
  text-align: center;
}

.mission-content p {
  font-size: 1.125rem;
  line-height: 1.8;
}

/* Responsive */
@media (max-width: 1024px) {
  .footer-grid {
    grid-template-columns: 1fr 1fr;
  }

  .feature-detail {
    grid-template-columns: 1fr;
    gap: 32px;
  }

  .feature-detail.reverse {
    direction: ltr;
  }
}

@media (max-width: 768px) {
  .nav-links,
  .nav-cta {
    display: none;
  }

  .hamburger {
    display: flex;
  }

  .hero {
    padding: 120px 0 60px;
  }

  .section {
    padding: 60px 0;
  }

  .stats-grid {
    grid-template-columns: 1fr 1fr;
  }

  .pricing-grid {
    grid-template-columns: 1fr;
  }

  .pricing-card.featured {
    transform: none;
  }

  .pricing-card.featured:hover {
    transform: translateY(-4px);
  }

  .footer-grid {
    grid-template-columns: 1fr;
    gap: 32px;
  }

  .contact-form {
    padding: 32px 24px;
